local ALIASES={["Mr. Green"]="Hero",["Mr. Yellow"]="Hero",["Mr. Brown"]="Hero"}
local function freeze(value,seen)
    if type(value)~='table' then return value end
    seen=seen or {};if seen[value] then return value end;seen[value]=true
    for _,child in pairs(value) do freeze(child,seen) end
    return table.freeze(value)
end
freeze(DATA);freeze(ALIASES)
local function integer(value) return type(value)=='number' and value==value and value>=0 and value<math.huge and value%1==0 end
local function byte(value) return integer(value) and value<=255 end
local function finite(value) return type(value)=='number' and value==value and value>-math.huge and value<math.huge end
local function result(p,frame,basis,source)
    return table.freeze({frameId=frame,namespace=p.namespace,spriteNamespace=p.spriteNamespace,
        bankRecipe=p.bankRecipe,frameBasis=basis,source=source,appliesDamage=false})
end
function Profiles.get(kind)
